let selectedTraditions = new Set(traditions.map(t => t.id));

// Указатель имя философа -> его традиции, по образцу conceptToRubrics.
const philosopherTraditions = {};
philosophers.forEach(p => { philosopherTraditions[p.nameRu] = p.traditions || []; });
function rebuildPhilosopherTraditions() {
  Object.keys(philosopherTraditions).forEach(k => delete philosopherTraditions[k]);
  philosophers.forEach(p => { philosopherTraditions[p.nameRu] = p.traditions || []; });
}

// ── Отбор по традициям ────────────────────────────────────────
// Традиция — признак ФИЛОСОФА, то есть той же оси, что и панель
// философов. Поэтому она соединяется с нею через «и», как рубрики,
// и НИКОГДА не переписывает набор философов: галочки там меняют
// только кнопки «только эти» и «+».
function philTraditionsSelected(name) {
  const tl = philosopherTraditions[name] || [];
  return tl.filter(t => selectedTraditions.has(t));
}
function philosopherPassesTraditions(name) {
  const tl = philosopherTraditions[name] || [];
  // Философ без традиций проходит всегда — иначе он исчезает молча.
  return tl.length === 0 || tl.some(t => selectedTraditions.has(t));
}
// both === true — оба конца (режимы, где и философы соединены «и»);
// both === false — хотя бы один (режимы «с соседними» и «внешние»).
function linkPassesTraditions(l, both) {
  const s = philosopherPassesTraditions(l.source.concept);
  const t = philosopherPassesTraditions(l.target.concept);
  return both ? (s && t) : (s || t);
}

