within_traditions: {
  name: 'Только внутри выбранных традиций',
  linkFilter: (l) => {
    if (!selectedRelations.has(l.type)) return false;
    if (!selectedPhilosophers.has(l.source.concept)) return false;
    if (!selectedPhilosophers.has(l.target.concept)) return false;
    if (l.source.concept === l.target.concept) return false;
    const s = philTraditionsSelected(l.source.concept);
    const t = philTraditionsSelected(l.target.concept);
    if (!s.some(x => t.includes(x))) return false;
    const sr = conceptToRubrics[l.source.id || l.source] || [];
    const tr = conceptToRubrics[l.target.id || l.target] || [];
    return (sr.length === 0 || sr.some(r => selectedRubrics.has(r)))
        && (tr.length === 0 || tr.some(r => selectedRubrics.has(r)));
  }
},
between_traditions: {
  name: 'Только между выбранными традициями',
  linkFilter: (l) => {
    if (!selectedRelations.has(l.type)) return false;
    if (!selectedPhilosophers.has(l.source.concept)) return false;
    if (!selectedPhilosophers.has(l.target.concept)) return false;
    if (l.source.concept === l.target.concept) return false;
