},

// Создаем фильтры традиций
const tradContainer = document.getElementById('traditionFilters');
if (tradContainer) {
  traditions.forEach(tr => {
    const members = philosophers.filter(p => (p.traditions || []).includes(tr.id));
    const item = document.createElement('div');
    item.className = 'legend-item';
    const hint = (tr.description || '').replace(/"/g, '&quot;');
    item.innerHTML = `
      <input type="checkbox" id="trad-${tr.id}" checked onchange="toggleTradition('${tr.id}')">
      <label for="trad-${tr.id}" title="${hint}" style="flex:1;">
        <span>${tr.name}<small style="color:#95a5a6;font-size:9px;"> (${members.length})</small></span>
      </label>
      <button class="tradition-pick" title="Оставить в отборе только этих философов"
          onclick="onlyTradition('${tr.id}')">=</button>
      <button class="tradition-pick" title="Добавить этих к выбранным философам"
          onclick="addTradition('${tr.id}')">+</button>
    `;
    tradContainer.appendChild(item);
  });
}

// Переключение традиции: сужает показ, набор философов НЕ трогает
function toggleTradition(traditionId) {
  if (selectedTraditions.has(traditionId)) selectedTraditions.delete(traditionId);
  else selectedTraditions.add(traditionId);
  applyFilters();
}

function selectAllTraditions() {
  selectedTraditions = new Set(traditions.map(t => t.id));
  traditions.forEach(t => {
    const cb = document.getElementById('trad-' + t.id);
    if (cb) cb.checked = true;
  });
  applyFilters();
}

function deselectAllTraditions() {
  selectedTraditions.clear();
  traditions.forEach(t => {
    const cb = document.getElementById('trad-' + t.id);
    if (cb) cb.checked = false;
  });
  applyFilters();
}

// Кнопки традиции правят НАБОР ФИЛОСОФОВ. Состояния они не хранят,
// поэтому порядок нажатий безразличен, а философ, состоящий в двух
// традициях, просто попадает в набор от каждой из них.
function traditionMembers(traditionId) {
  return philosophers.filter(p => (p.traditions || []).includes(traditionId))
             .map(p => p.nameRu);
}

function syncPhilosopherCheckboxes() {
  Object.keys(philosopherConcepts).forEach(name => {
    const cb = document.getElementById('phil-' + name);
    if (cb) cb.checked = selectedPhilosophers.has(name);
  });
}

function onlyTradition(traditionId) {
  selectedPhilosophers = new Set(traditionMembers(traditionId));
  syncPhilosopherCheckboxes();
  applyFilters();
}

function addTradition(traditionId) {
  traditionMembers(traditionId).forEach(name => selectedPhilosophers.add(name));
  syncPhilosopherCheckboxes();
  applyFilters();
}

// Философ, выбранный галочкой, но отсечённый традициями, не исчезает
// из панели и не теряет галочки — он приглушается. Так видно и что
// выбрано, и что из выбранного сейчас действует.
function updatePhilosopherDimming() {
  Object.keys(philosopherConcepts).forEach(name => {
    const cb = document.getElementById('phil-' + name);
    if (!cb) return;
    const row = cb.closest('.legend-item');
    if (!row) return;
    const dim = cb.checked && !philosopherPassesTraditions(name);
    row.style.opacity = dim ? '0.35' : '';
    row.title = dim ? 'Отсечён отбором по традициям' : '';
  });
}

